  'http://localhost:8095/#/pages/rescue/index'];
const p = spawn(edge, args, { stdio: 'ignore' });
function sleep(ms){return new Promise(r=>setTimeout(r,ms));}
async function getWs(){
  for(let i=0;i<40;i++){
    try{
      const r = await fetch(`http://127.0.0.1:${port}/json/list`);
      const j = await r.json();
      const page = j.find(t=>t.type==='page' && t.webSocketDebuggerUrl);
      if(page) return page.webSocketDebuggerUrl;
    }catch(e){}
    await sleep(300);
  }
  throw new Error('no ws');
}
const wsUrl = await getWs();
const ws = new WebSocket(wsUrl);
let id=0; const pending=new Map();
ws.addEventListener('message',ev=>{
  const m = JSON.parse(ev.data);
  if(m.id && pending.has(m.id)){ pending.get(m.id)(m); pending.delete(m.id); }
});
function cmd(method,params={}){
  return new Promise(res=>{ const _id=++id; pending.set(_id,res); ws.send(JSON.stringify({id:_id,method,params})); });
}
await new Promise(r=>ws.addEventListener('open',r));
await sleep(4000);
const expr = `(()=>{
  const cs=[...document.querySelectorAll('.field-count')];
  const wraps=[...document.querySelectorAll('.field-textarea-wrap')];
